def batch_quote(rows):
    result = []
    for row in rows:
        subtotal = row['unit_cents'] * row['quantity']
        if row['tier'] == 'gold' and row['quantity'] >= 10:
            subtotal -= subtotal // 10
        result.append((row['id'], subtotal))
    return result

